package com.fitforge.nutrition;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fitforge.auth.AppUserRepository;
import com.fitforge.ai.AiDtos;
import com.fitforge.progress.WeightRepository;
import com.fitforge.progress.WeightEntry;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*; import java.time.temporal.TemporalAdjusters; import java.util.*;

@Service
public class NutritionModuleService {
 private final AppUserRepository users; private final IndianFoodItemRepository foods; private final FoodDiaryRepository diary; private final FavoriteMealRepository favorites; private final FatLossMissionRepository missions; private final HydrationFiberRepository hydration; private final GroceryListRepository groceries; private final NutritionReminderRepository reminders; private final ObjectMapper mapper; private final DailyCalorieBalanceRepository balances; private final DeadlineChangeRepository deadlineChanges; private final WeightRepository weights;
 public NutritionModuleService(AppUserRepository users,IndianFoodItemRepository foods,FoodDiaryRepository diary,FavoriteMealRepository favorites,FatLossMissionRepository missions,HydrationFiberRepository hydration,GroceryListRepository groceries,NutritionReminderRepository reminders,ObjectMapper mapper,DailyCalorieBalanceRepository balances,DeadlineChangeRepository deadlineChanges,WeightRepository weights){this.users=users;this.foods=foods;this.diary=diary;this.favorites=favorites;this.missions=missions;this.hydration=hydration;this.groceries=groceries;this.reminders=reminders;this.mapper=mapper;this.balances=balances;this.deadlineChanges=deadlineChanges;this.weights=weights;}
 private Long uid(String email){return users.findByEmail(email).orElseThrow(()->new IllegalArgumentException("Authenticated user not found")).getId();}
 public List<NutritionModuleDtos.Food> foods(String email,String search,boolean includeCustom){Long id=uid(email);String q=search==null?"":search.trim().toLowerCase(Locale.ROOT);return foods.findByUserIdIsNullOrUserIdOrderByNameAsc(id).stream().filter(f->includeCustom||!f.isCustom()).filter(f->q.isBlank()||f.getName().toLowerCase(Locale.ROOT).contains(q)).map(this::foodDto).toList();}
 @Transactional public NutritionModuleDtos.Food customFood(String email,NutritionModuleDtos.CustomFoodInput i){var f=foods.save(new IndianFoodItem(i.name().trim(),i.calories(),i.proteinG(),i.carbsG(),i.fatG(),i.fiberG(),i.defaultUnit(),prep(i.preparationType()),i.servingGrams(),uid(email),true));return foodDto(f);}
 public NutritionModuleDtos.DiaryDay day(String email,LocalDate date){return day(uid(email),date);}
 private NutritionModuleDtos.DiaryDay day(Long id,LocalDate date){var es=diary.findByUserIdAndEntryDateOrderByLoggedAtAsc(id,date);double[] t=totals(es);return new NutritionModuleDtos.DiaryDay(date,t[0],t[1],t[2],t[3],t[4],es.stream().map(this::diaryDto).toList());}
 @Transactional public NutritionModuleDtos.Diary addDiary(String email,NutritionModuleDtos.DiaryInput i){validateCategory(i.mealCategory());if(i.preparationType()!=null)prep(i.preparationType());Long id=uid(email);return diaryDto(diary.save(new FoodDiaryEntry(id,calculateFromCatalog(id,i))));}
 @Transactional public NutritionModuleDtos.Diary updateDiary(String email,Long id,NutritionModuleDtos.DiaryInput i){validateCategory(i.mealCategory());if(i.preparationType()!=null)prep(i.preparationType());Long user=uid(email);var e=diary.findByIdAndUserId(id,user).orElseThrow(()->new IllegalArgumentException("Diary entry not found"));e.update(calculateFromCatalog(user,i));return diaryDto(e);}
 @Transactional public void deleteDiary(String email,Long id){diary.delete(diary.findByIdAndUserId(id,uid(email)).orElseThrow(()->new IllegalArgumentException("Diary entry not found")));}
 public List<NutritionModuleDtos.Favorite> favorites(String email){return favorites.findByUserIdOrderByNameAsc(uid(email)).stream().map(this::favoriteDto).toList();}
 @Transactional public NutritionModuleDtos.Favorite addFavorite(String email,NutritionModuleDtos.FavoriteInput i){Long id=uid(email);double[] t=favoriteTotals(i.items());String json=write(i.items());var f=favorites.save(new FavoriteMeal(email,id,i.mealName(),json,(int)Math.round(t[0]),t[1],t[2],t[3],t[4],null));return favoriteDto(f);}
 @Transactional public void deleteFavorite(String email,Long id){favorites.delete(favorites.findByIdAndUserId(id,uid(email)).orElseThrow(()->new IllegalArgumentException("Favorite meal not found")));}
 @Transactional public NutritionModuleDtos.DiaryDay logFavorite(String email,Long id,LocalDate date,String category){validateCategory(category);Long user=uid(email);var f=favorites.findByIdAndUserId(id,user).orElseThrow(()->new IllegalArgumentException("Favorite meal not found"));try{var items=mapper.readValue(f.getItemsJson(),new TypeReference<List<NutritionModuleDtos.FavoriteItemInput>>(){});for(var item:items){var in=new NutritionModuleDtos.DiaryInput(date,category,item.foodName(),item.quantity(),item.unit(),item.preparationType(),item.calories(),item.proteinG(),item.carbsG(),item.fatG(),item.fiberG(),null);diary.save(new FoodDiaryEntry(user,in));}}catch(Exception e){throw new IllegalStateException("Favorite meal items could not be read");}return day(user,date);}
 public NutritionModuleDtos.Mission mission(String email,LocalDate date){Long id=uid(email);var m=missions.findByUserId(id).orElseGet(()->missions.save(new FatLossMission(id,new NutritionModuleDtos.MissionInput(null,null,null,null,null,null))));double consumed=day(id,date).calories();var prior=diary.findByUserIdAndEntryDateBetweenOrderByEntryDateAscLoggedAtAsc(id,m.getStartDate(),date);Map<LocalDate,Double> byDate=new HashMap<>();prior.forEach(e->byDate.merge(e.getEntryDate(),e.getCalories(),Double::sum));double cumulative=byDate.entrySet().stream().mapToDouble(e->m.getMaintenanceCalories()-e.getValue()).sum();return missionDto(m,consumed,cumulative);}
 @Transactional public NutritionModuleDtos.CalorieBalance recordBalance(String email,NutritionModuleDtos.CalorieBalanceInput input){Long id=uid(email);var m=missionEntity(id);LocalDate date=input.entryDate();double tdee=input.estimatedTdee()==null?m.getMaintenanceCalories():input.estimatedTdee();double plan=input.plannedDeficit()==null?Math.max(0,tdee-m.getDailyCalorieBudget()):Math.max(0,input.plannedDeficit());double consumed=day(id,date).calories();double actual=tdee-consumed;double previous=0;if(!date.isBefore(m.getStartDate())){LocalDate priorEnd=date.minusDays(1);if(!priorEnd.isBefore(m.getStartDate()))previous=balances.findByUserIdAndEntryDateBetweenOrderByEntryDateAsc(id,m.getStartDate(),priorEnd).stream().reduce((x,y)->y).map(DailyCalorieBalance::getPendingGapKcal).orElse(0.0);}double credited=Math.min(plan,Math.max(0,actual));double pending=previous+Math.max(0,plan-credited);var b=balances.findByUserIdAndEntryDate(id,date).orElseGet(()->new DailyCalorieBalance(id,date,tdee,consumed,plan,pending));b.update(tdee,consumed,plan,pending);return balanceDto(balances.save(b));}
 public NutritionModuleDtos.BacklogReview backlog(String email){Long id=uid(email);var m=missionEntity(id);double gap=balances.findTopByUserIdOrderByEntryDateDesc(id).map(DailyCalorieBalance::getPendingGapKcal).orElse(0.0);long remaining=Math.max(0,java.time.temporal.ChronoUnit.DAYS.between(LocalDate.now(),m.getRevisedDeadline()));return new NutritionModuleDtos.BacklogReview(gap,m.getOriginalDeadline(),m.getRevisedDeadline(),remaining,false,"",Math.max(0,m.getMaintenanceCalories()-m.getDailyCalorieBudget()),Math.max(0,m.getMaintenanceCalories()-m.getDailyCalorieBudget())*7,balances.findByUserIdAndEntryDateBetweenOrderByEntryDateAsc(id,m.getStartDate(),LocalDate.now()).stream().map(this::balanceDto).toList());}
 @Transactional public NutritionModuleDtos.BacklogReview reviewBacklog(String email){Long id=uid(email);var m=missionEntity(id);LocalDate today=LocalDate.now(),week=today.minusDays(6);double plan=Math.max(0,m.getMaintenanceCalories()-m.getDailyCalorieBudget());LocalDate previousEnd=week.minusDays(1);double pending=previousEnd.isBefore(m.getStartDate())?0:balances.findByUserIdAndEntryDateBetweenOrderByEntryDateAsc(id,m.getStartDate(),previousEnd).stream().reduce((x,y)->y).map(DailyCalorieBalance::getPendingGapKcal).orElse(0.0);
  for(LocalDate d=week.isBefore(m.getStartDate())?m.getStartDate():week;!d.isAfter(today);d=d.plusDays(1)){LocalDate reviewDay=d;double consumed=day(id,reviewDay).calories(),actual=m.getMaintenanceCalories()-consumed,credited=Math.min(plan,Math.max(0,actual));pending+=Math.max(0,plan-credited);double currentPending=pending;var b=balances.findByUserIdAndEntryDate(id,reviewDay).orElseGet(()->new DailyCalorieBalance(id,reviewDay,m.getMaintenanceCalories(),consumed,plan,currentPending));b.update(m.getMaintenanceCalories(),consumed,plan,currentPending);balances.save(b);}
  double currentWeight=weights.findTopByUserEmailOrderByDateDesc(email).map(w->w.getWeightKg()).orElse(m.getStartWeightKg());double weeklyRate=observedLossPerWeek(email,m);double plannedRate=Math.min(.75,plan*7/7700.0);double rate=weeklyRate>0?Math.min(.75,weeklyRate):Math.max(.1,plannedRate);double remainKg=Math.max(0,currentWeight-m.getTargetWeightKg());long weightDays=remainKg==0?0:(long)Math.ceil(remainKg/(rate/7));long gapDays=plan<=0?30:(long)Math.ceil(pending/plan);long projection=Math.max(weightDays,gapDays);LocalDate old=m.getRevisedDeadline(),revised=today.plusDays(projection);if(revised.isBefore(old))revised=old;boolean changed=!revised.equals(old);String notification=changed?"Your goal deadline was extended to reflect recorded progress. Keep the normal training plan; no catch-up cardio or crash dieting is needed.":"Your goal timeline remains on track; no extra exercise is owed.";m.reviseDeadline(revised);missions.save(m);if(changed)deadlineChanges.save(new DeadlineChange(id,m.getOriginalDeadline(),revised,notification,plan,plan*7));List<NutritionModuleDtos.CalorieBalance> history=balances.findByUserIdAndEntryDateBetweenOrderByEntryDateAsc(id,m.getStartDate(),today).stream().map(this::balanceDto).toList();return new NutritionModuleDtos.BacklogReview(pending,m.getOriginalDeadline(),revised,Math.max(0,java.time.temporal.ChronoUnit.DAYS.between(today,revised)),changed,notification,plan,plan*7,history);}
 public List<DeadlineChange> deadlineHistory(String email){return deadlineChanges.findByUserIdOrderByChangedAtDesc(uid(email));}
 @Transactional public NutritionModuleDtos.Mission saveMission(String email,NutritionModuleDtos.MissionInput i,LocalDate date){Long id=uid(email);var m=missions.findByUserId(id).orElseGet(()->new FatLossMission(id,i));if(m.getId()!=null)m.update(i);m=missions.save(m);double consumed=day(id,date).calories();var entries=diary.findByUserIdAndEntryDateBetweenOrderByEntryDateAscLoggedAtAsc(id,m.getStartDate(),date);Map<LocalDate,Double> byDate=new HashMap<>();entries.forEach(e->byDate.merge(e.getEntryDate(),e.getCalories(),Double::sum));int maintenance=m.getMaintenanceCalories();double cumulative=byDate.entrySet().stream().mapToDouble(e->maintenance-e.getValue()).sum();return missionDto(m,consumed,cumulative);}
  public NutritionModuleDtos.Analytics analytics(String email,int days,LocalDate from,LocalDate to){Long id=uid(email);LocalDate end=to==null?LocalDate.now():to;LocalDate start=from==null?end.minusDays(Math.max(1,days)-1L):from;if(start.isAfter(end))throw new IllegalArgumentException("startDate must be on or before endDate");if(from==null&&days!=7&&days!=30&&days!=90)throw new IllegalArgumentException("days must be 7, 30, or 90");var es=diary.findByUserIdAndEntryDateBetweenOrderByEntryDateAscLoggedAtAsc(id,start,end);Map<LocalDate,List<FoodDiaryEntry>> map=new HashMap<>();es.forEach(e->map.computeIfAbsent(e.getEntryDate(),k->new ArrayList<>()).add(e));int n=(int)(end.toEpochDay()-start.toEpochDay()+1);var mission=missions.findByUserId(id).orElse(null);double target=mission==null?1800:mission.getDailyCalorieBudget();double maintenance=mission==null?1800:mission.getMaintenanceCalories();double proteinTarget=mission==null?144:mission.getStartWeightKg()*1.6;List<NutritionModuleDtos.DailyAnalytics> daily=new ArrayList<>();List<LocalDate> missed=new ArrayList<>();double[] sum=new double[5];LocalDate best=null;double bestScore=Double.MAX_VALUE;int consistent=0,loggedDays=0;double deficit=0;
   for(LocalDate d=start;!d.isAfter(end);d=d.plusDays(1)){var list=map.getOrDefault(d,List.of());double[] t=totals(list);boolean c=!list.isEmpty()&&t[0]<=target;boolean p=t[1]>=proteinTarget;daily.add(new NutritionModuleDtos.DailyAnalytics(d,t[0],t[1],t[2],t[3],t[4],c,p));if(!c||!p)missed.add(d);if(c&&p)consistent++;if(!list.isEmpty()){loggedDays++;deficit+=maintenance-t[0];}for(int j=0;j<5;j++)sum[j]+=t[j];double score=Math.abs(target-t[0])+(p?0:Math.max(0,proteinTarget-t[1])*2);if(!list.isEmpty()&&score<bestScore){bestScore=score;best=d;}}
   return new NutritionModuleDtos.Analytics(start,end,sum[0]/n,sum[1]/n,sum[2]/n,sum[3]/n,sum[4]/n,loggedDays==0?0:deficit/loggedDays,100.0*consistent/n,best==null?null:best.toString(),missed,daily);
 }
 public NutritionModuleDtos.Hydration hydration(String email,LocalDate date){Long id=uid(email);var h=hydration.findByUserIdAndLogDate(id,date).orElse(new HydrationFiberLog(id,date,new NutritionModuleDtos.HydrationInput(0,null,null)));double fiber=totals(diary.findByUserIdAndEntryDateOrderByLoggedAtAsc(id,date))[4];return new NutritionModuleDtos.Hydration(date,h.getWaterMl(),h.getWaterGoalMl(),h.getFiberTargetG(),fiber,Math.max(0,h.getFiberTargetG()-fiber));}
 @Transactional public NutritionModuleDtos.Hydration saveHydration(String email,LocalDate date,NutritionModuleDtos.HydrationInput i){Long id=uid(email);var h=hydration.findByUserIdAndLogDate(id,date).orElseGet(()->new HydrationFiberLog(id,date,i));h.update(i);hydration.save(h);return hydration(email,date);}
 public NutritionModuleDtos.Grocery grocery(String email){Long id=uid(email);LocalDate week=LocalDate.now().with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY));return groceries.findByUserIdAndWeekStartDate(id,week).map(this::groceryDto).orElse(new NutritionModuleDtos.Grocery(null,week,"[]"));}
 @Transactional public NutritionModuleDtos.Grocery putGrocery(String email,NutritionModuleDtos.GroceryInput i){Long id=uid(email);LocalDate week=i.weekStartDate().with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY));var g=groceries.findByUserIdAndWeekStartDate(id,week).orElseGet(()->new GroceryList(id,week,i.itemsJson()));g.setItemsJson(i.itemsJson());return groceryDto(groceries.save(g));}
 public NutritionModuleDtos.Reminders reminders(String email){var p=reminders.findByUserId(uid(email)).orElse(null);return p==null?new NutritionModuleDtos.Reminders(null,null,null,null,null):new NutritionModuleDtos.Reminders(p.getMealReminderJson(),p.getProteinReminderJson(),p.getWaterReminderJson(),p.getWeightReminderJson(),p.getEodVerdictReminderJson());}
 @Transactional public NutritionModuleDtos.Reminders putReminders(String email,NutritionModuleDtos.ReminderInput i){Long id=uid(email);var p=reminders.findByUserId(id).orElseGet(()->new NutritionReminderPref(id));p.update(i);reminders.save(p);return reminders(email);}
 public double proteinTarget(String email){return missions.findByUserId(uid(email)).map(m->m.getStartWeightKg()*1.6).orElse(144.0);}
 public double dailyCalorieBudget(String email){return missions.findByUserId(uid(email)).map(FatLossMission::getDailyCalorieBudget).orElse(1500);}
 public AiProteinData proteinData(String email,LocalDate date){Long id=uid(email);double consumed=totals(diary.findByUserIdAndEntryDateOrderByLoggedAtAsc(id,date))[1];double target=proteinTarget(email);Map<String,IndianFoodItem> byName=new HashMap<>();foods.findByUserIdIsNullOrUserIdOrderByNameAsc(id).forEach(f->byName.put(f.getName().toLowerCase(Locale.ROOT),f));
  var options=List.of(
   proteinOption("chicken-curd","Chicken breast + curd",List.of(new ProteinChoice("Chicken breast, cooked",120,"g"),new ProteinChoice("Plain curd",100,"g")),byName),
   proteinOption("egg-yogurt","Eggs + Greek yogurt",List.of(new ProteinChoice("Whole egg",2,"piece"),new ProteinChoice("Greek yogurt, plain",150,"g")),byName),
   proteinOption("soy-paneer","Soy chunks + paneer",List.of(new ProteinChoice("Soy chunks, dry",35,"g"),new ProteinChoice("Paneer",75,"g")),byName));
  return new AiProteinData(target,consumed,Math.max(0,target-consumed),options);
 }
 private AiDtos.ProteinOption proteinOption(String id,String name,List<ProteinChoice> choices,Map<String,IndianFoodItem> foods){List<AiDtos.ProteinLogItem> items=new ArrayList<>();double[] t=new double[5];for(var c:choices){var f=foods.get(c.name().toLowerCase(Locale.ROOT));if(f==null)continue;double grams=c.unit().equals("piece")?c.quantity()*f.getServingGrams():c.quantity();double scale=grams/100.0;double cal=f.getCalories()*scale,p=f.getProteinG()*scale,carb=f.getCarbsG()*scale,fat=f.getFatG()*scale,fiber=f.getFiberG()*scale;t[0]+=cal;t[1]+=p;t[2]+=carb;t[3]+=fat;t[4]+=fiber;items.add(new AiDtos.ProteinLogItem(f.getName(),c.quantity(),c.unit(),f.getPreparationType(),cal,p,carb,fat,fiber));}return new AiDtos.ProteinOption(id,"SNACKS",name,items,t[0],t[1],t[2],t[3],t[4]);}
 public record AiProteinData(double target,double consumed,double remaining,List<AiDtos.ProteinOption> options){}
 private record ProteinChoice(String name,double quantity,String unit){}
 public List<NutritionModuleDtos.Diary> recentDiary(String email,LocalDate from,LocalDate to){return diary.findByUserIdAndEntryDateBetweenOrderByEntryDateAscLoggedAtAsc(uid(email),from,to).stream().map(this::diaryDto).toList();}
 private NutritionModuleDtos.Food foodDto(IndianFoodItem f){return new NutritionModuleDtos.Food(f.getId(),f.getName(),f.getCalories(),f.getProteinG(),f.getCarbsG(),f.getFatG(),f.getFiberG(),f.getDefaultUnit(),f.getPreparationType(),f.isCustom(),f.getUserId(),f.getServingGrams());}
 private NutritionModuleDtos.Diary diaryDto(FoodDiaryEntry e){return new NutritionModuleDtos.Diary(e.getId(),e.getUserId(),e.getEntryDate(),e.getLoggedAt(),e.getMealCategory(),e.getFoodName(),e.getQuantity(),e.getUnit(),e.getPreparationType(),e.getCalories(),e.getProteinG(),e.getCarbsG(),e.getFatG(),e.getFiberG(),e.getScanConfidence());}
 private NutritionModuleDtos.Favorite favoriteDto(FavoriteMeal f){return new NutritionModuleDtos.Favorite(f.getId(),f.getName(),f.getItemsJson(),f.getCalories(),f.getProteinG(),f.getCarbsG(),f.getFatG(),f.getFiberG()==null?0:f.getFiberG());}
 private NutritionModuleDtos.Grocery groceryDto(GroceryList g){return new NutritionModuleDtos.Grocery(g.getId(),g.getWeekStartDate(),g.getItemsJson());}
 private NutritionModuleDtos.Mission missionDto(FatLossMission m,double c,double cumulative){return new NutritionModuleDtos.Mission(m.getId(),m.getStartWeightKg(),m.getTargetWeightKg(),m.getStartDate(),m.getTargetDate(),m.getMaintenanceCalories(),m.getDailyCalorieBudget(),c,m.getDailyCalorieBudget()-c,m.getMaintenanceCalories()-c,cumulative);}
 private FatLossMission missionEntity(Long id){return missions.findByUserId(id).orElseGet(()->missions.save(new FatLossMission(id,new NutritionModuleDtos.MissionInput(null,null,null,null,null,null))));}
 private NutritionModuleDtos.CalorieBalance balanceDto(DailyCalorieBalance b){return new NutritionModuleDtos.CalorieBalance(b.getId(),b.getEntryDate(),b.getEstimatedTdee(),b.getConsumedCalories(),b.getPlannedDeficit(),b.getActualDeficit(),b.getPendingGapKcal());}
 private double observedLossPerWeek(String email,FatLossMission m){var entries=weights.findByUserEmailAndDateBetweenOrderByDateAsc(email,m.getStartDate(),LocalDate.now());if(entries.size()<2)return 0;LocalDate cutoff=LocalDate.now().minusDays(7);var old=entries.stream().filter(w->!w.getDate().isAfter(cutoff)).toList();var recent=entries.stream().filter(w->!w.getDate().isBefore(cutoff)).toList();double first=old.isEmpty()?entries.get(0).getWeightKg():old.stream().mapToDouble(WeightEntry::getWeightKg).average().orElse(entries.get(0).getWeightKg());double last=recent.isEmpty()?entries.get(entries.size()-1).getWeightKg():recent.stream().mapToDouble(WeightEntry::getWeightKg).average().orElse(entries.get(entries.size()-1).getWeightKg());long days=Math.max(1,java.time.temporal.ChronoUnit.DAYS.between(entries.get(0).getDate(),entries.get(entries.size()-1).getDate()));return Math.max(0,(first-last)*7.0/days);}
 private String prep(String s){String p=s.toUpperCase(Locale.ROOT);if(!p.equals("RAW")&&!p.equals("COOKED"))throw new IllegalArgumentException("preparationType must be RAW or COOKED");return p;}
 private NutritionModuleDtos.DiaryInput calculateFromCatalog(Long id,NutritionModuleDtos.DiaryInput i){if(i.scanConfidence()!=null)return i;var f=foods.findFirstByUserIdAndNameIgnoreCase(id,i.foodName()).or(()->foods.findFirstByUserIdIsNullAndNameIgnoreCase(i.foodName())).orElse(null);if(f==null)return i;String unit=i.unit().trim().toLowerCase(Locale.ROOT);double grams;if(unit.equals("g")||unit.equals("gram")||unit.equals("grams")||unit.equals("ml"))grams=i.quantity();else if(unit.equalsIgnoreCase(f.getDefaultUnit()))grams=i.quantity()*f.getServingGrams();else return i;double factor=grams/100.0;return new NutritionModuleDtos.DiaryInput(i.entryDate(),i.mealCategory(),i.foodName(),i.quantity(),i.unit(),i.preparationType()==null?f.getPreparationType():i.preparationType(),f.getCalories()*factor,f.getProteinG()*factor,f.getCarbsG()*factor,f.getFatG()*factor,f.getFiberG()*factor,null);}
 private void validateCategory(String s){if(!Set.of("BREAKFAST","LUNCH","SNACKS","PRE_WORKOUT","DINNER").contains(s.toUpperCase(Locale.ROOT)))throw new IllegalArgumentException("mealCategory must be BREAKFAST, LUNCH, SNACKS, PRE_WORKOUT, or DINNER");}
 private double[] totals(List<FoodDiaryEntry> es){double[] t=new double[5];for(var e:es){t[0]+=e.getCalories();t[1]+=e.getProteinG();t[2]+=e.getCarbsG();t[3]+=e.getFatG();t[4]+=e.getFiberG();}return t;}
 private double[] favoriteTotals(List<NutritionModuleDtos.FavoriteItemInput> items){double[] t=new double[5];for(var e:items){t[0]+=e.calories();t[1]+=e.proteinG();t[2]+=e.carbsG();t[3]+=e.fatG();t[4]+=e.fiberG();}return t;}
 private String write(Object o){try{return mapper.writeValueAsString(o);}catch(Exception e){throw new IllegalArgumentException("Could not serialize items");}}
}
